<template>
  <div id="app">
    <div class="container">
      <!-- 左侧：事件面板 -->
      <div class="event-panel">
        <!-- 返回按钮 -->
        <div 
          :class="['action-button', { 'disabled': viewMode === 'year' }]" 
          @click="viewMode === 'month' && exitMonth()" 
          :title="viewMode === 'month' ? '返回全年' : '返回'"
        >
          <el-icon :size="18"><Back /></el-icon>
        </div>

        <!-- 添加按钮 -->
        <div class="action-button" @click="showAddDialog = true" title="添加">
          <el-icon :size="18"><Plus /></el-icon>
        </div>
        
        <!-- 编辑模式按钮 -->
        <div 
          :class="['action-button', { 'active': isEditMode }]" 
          @click="toggleEditMode" 
          title="编辑"
        >
          <el-icon :size="18"><Edit /></el-icon>
        </div>

        <!-- 分隔线 -->
        <div class="divider"></div>

        <!-- 事件颜色圆圈列表 -->
        <div class="event-circles">
          <el-tooltip
            v-for="event in events" 
            :key="event.id"
            placement="right"
            effect="dark"
          >
            <template #content>
              <div>{{ event.name }}</div>
            </template>
            <div 
              :class="['event-circle', { 'selected': selectedEventId === event.id }]"
              :style="{ backgroundColor: event.color }"
              @click="handleEventClick(event.id)"
            >
              <!-- 事件名称首字 -->
              <span class="event-initial">{{ event.name.charAt(0) }}</span>
              
              <!-- 编辑模式下显示小编辑图标 -->
              <div v-if="isEditMode" class="edit-badge">
                <el-icon :size="12"><Edit /></el-icon>
              </div>
            </div>
          </el-tooltip>
        </div>

        <!-- 弹性间距 -->
        <div class="spacer"></div>

        <!-- 更多按钮 -->
        <div class="more-button" @click="showEventsManageDialog = true">
          <span class="more-dots">⋯</span>
        </div>

        <!-- 分隔线 -->
        <div class="divider"></div>

        <!-- 清除颜色按钮 -->
        <div 
          :class="['action-button', 'clear-button', { 'active': isClearMode }]" 
          @click="toggleClearMode"
        >
          <el-icon :size="18"><Delete /></el-icon>
        </div>

        <!-- 分隔线 -->
        <div class="divider"></div>

        <!-- 年份选择器（纵向） -->
        <div class="year-selector-vertical">
          <div class="year-button" @click="changeYear(1)" title="下一年">
            <el-icon :size="12"><ArrowUp /></el-icon>
          </div>
          <div class="year-display">
            {{ currentYear }}
          </div>
          <div class="year-button" @click="changeYear(-1)" title="上一年">
            <el-icon :size="12"><ArrowDown /></el-icon>
          </div>
        </div>

        <!-- 分隔线 -->
        <div class="divider"></div>

        <!-- 导入导出按钮 -->
        <el-tooltip content="导入数据" placement="right" effect="dark">
          <div class="action-button" @click="triggerImport">
            <el-icon :size="18"><Upload /></el-icon>
          </div>
        </el-tooltip>
        <el-tooltip content="导出数据" placement="right" effect="dark">
          <div class="action-button" @click="exportData">
            <el-icon :size="18"><Download /></el-icon>
          </div>
        </el-tooltip>

        <!-- 隐藏的文件输入 -->
        <input 
          ref="fileInput" 
          type="file" 
          accept=".json" 
          @change="importData" 
          style="display: none;"
        />
      </div>

      <!-- 事件管理对话框 -->
      <el-dialog 
        v-model="showEventsManageDialog"
        width="80%"
        class="events-manage-dialog"
      >
        <div class="manage-header">
          <!-- 搜索框 -->
          <el-input
            v-model="searchKeyword"
            placeholder="搜索"
            clearable
            class="search-input"
          >
            <template #prefix>
              <el-icon><Search /></el-icon>
            </template>
          </el-input>

          <!-- 操作按钮 -->
          <div class="manage-actions">
            <el-tooltip content="添加" placement="top" effect="dark">
              <div 
                class="action-button"
                @click="showAddDialog = true;"
              >
                <el-icon :size="18"><Plus /></el-icon>
              </div>
            </el-tooltip>
            <el-tooltip content="编辑" placement="top" effect="dark">
              <div 
                :class="['action-button', { 'active': isEditMode }]"
                @click="toggleEditMode"
              >
                <el-icon :size="18"><Edit /></el-icon>
              </div>
            </el-tooltip>
          </div>
        </div>

        <!-- 事件列表 -->
        <div class="manage-event-list">
          <el-tooltip
            v-for="event in filteredEvents" 
            :key="event.id"
            placement="bottom"
            effect="dark"
          >
            <template #content>
              <div>{{ event.name.split(' ')[1] }}</div>
            </template>
            <div 
              :class="['manage-event-circle', { 'selected': selectedEventId === event.id }]"
              :style="{ backgroundColor: event.color }"
              @click="handleManageEventClick(event.id)"
            >
              <span class="manage-event-initial">{{ event.name.charAt(0) }}</span>
              <div v-if="isEditMode" class="manage-edit-badge">
                <el-icon :size="12"><Edit /></el-icon>
              </div>
            </div>
          </el-tooltip>
          <div v-if="filteredEvents.length === 0" class="no-events-manage">
            {{ searchKeyword ? '未找到' : '暂无' }}
          </div>
        </div>

        <template #footer>
          <el-button @click="showEventsManageDialog = false">关闭</el-button>
        </template>
      </el-dialog>

      <!-- 日期详情对话框 -->
      <el-dialog 
        v-model="showDayDetailDialog" 
        width="500px"
        class="day-detail-dialog"
      >
        <div class="day-detail-content">
          <div 
            v-for="(eventInfo, index) in selectedDayInfo.events" 
            :key="eventInfo.id"
            class="event-detail-card"
            :style="{ 
              backgroundColor: eventInfo.color,
              marginBottom: index < selectedDayInfo.events.length - 1 ? '12px' : '0'
            }"
          >
            <div class="event-card-header">
              <div class="event-card-icon">
                {{ eventInfo.name.charAt(0) }}
              </div>
              <div class="event-card-title">
                {{ eventInfo.name.split(' ')[1]}}      
              </div>
            </div>
            <div v-if="eventInfo.note" class="event-card-note">
              {{ eventInfo.note }}
            </div>
          </div>
          <div v-if="selectedDayInfo.events.length === 0" class="no-events">
            暂无
          </div>
        </div>
        <template #footer>
          <el-button @click="showDayDetailDialog = false">关闭</el-button>
        </template>
      </el-dialog>

      <!-- 添加事件对话框 -->
      <el-dialog 
        v-model="showAddDialog" 
        title="添加" 
        width="400px"
      >
        <el-form :model="newEventForm" label-width="80px">
          <el-form-item label="名称">
            <el-input 
              v-model="newEventForm.name" 
              placeholder="请输入名称"
            />
          </el-form-item>
          <el-form-item label="颜色">
            <el-color-picker 
              v-model="newEventForm.color" 
              :predefine="predefineColors"
            />
          </el-form-item>
          <el-form-item label="备注">
            <el-input 
              v-model="newEventForm.note" 
              type="textarea"
              :rows="10"
              placeholder="请输入备注"
              maxlength="2000"
              show-word-limit
            />
          </el-form-item>
        </el-form>
        <template #footer>
          <el-button @click="showAddDialog = false">取消</el-button>
          <el-button type="primary" @click="addEvent">确定</el-button>
        </template>
      </el-dialog>

      <!-- 编辑事件对话框 -->
      <el-dialog 
        v-model="showEditDialog" 
        title="编辑" 
        width="400px"
      >
        <el-form :model="editEventForm" label-width="80px">
          <el-form-item label="名称">
            <el-input 
              v-model="editEventForm.name" 
              placeholder="请输入名称"
            />
          </el-form-item>
          <el-form-item label="颜色">
            <el-color-picker 
              v-model="editEventForm.color" 
              :predefine="predefineColors"
            />
          </el-form-item>
          <el-form-item label="备注">
            <el-input 
              v-model="editEventForm.note" 
              type="textarea"
              :rows="10"
              placeholder="请输入备注"
              maxlength="2000"
              show-word-limit
            />
          </el-form-item>
        </el-form>
        <template #footer>
          <el-button @click="showEditDialog = false">取消</el-button>
          <el-button type="danger" @click="confirmDeleteEvent">删除</el-button>
          <el-button type="primary" @click="saveEditEvent">保存</el-button>
        </template>
      </el-dialog>

      <!-- 右侧：日历区域 -->
      <div class="calendar-area">
        <!-- 全局统计浮动框 -->
        <div class="global-stats-float">
          <div class="global-stat-item">
            <img src="./assets/p_g.png" class="global-stat-icon"/>
            <span class="global-stat-text">{{ getTotalEventTypes() }}</span>
          </div>
          <div class="global-stat-item">
            <img src="./assets/t_g.png" class="global-stat-icon"/>
            <span class="global-stat-text">{{ getTotalEventCount() }}</span>
          </div>
        </div>

        <!-- 全年日历视图 -->
        <div v-if="viewMode === 'year'" class="year-view">
          <div 
            v-for="month in 12" 
            :key="month"
            class="month-card"
            @click="enterMonth(month)"
          >
            <div class="month-header-row">
              <div class="month-header">{{ month }}月</div>
              <div class="month-stats">
                <div class="stat-item">
                  <img src="./assets/p.png" class="stat-icon"/>
                  <span class="stat-text">{{ getMonthEventTypes(currentYear, month) }}</span>
                </div>
                <div class="stat-item">
                  <img src="./assets/t.png" class="stat-icon"/>
                  <span class="stat-text">{{ getMonthEventCount(currentYear, month) }}</span>
                </div>
              </div>
            </div>
            <div class="mini-calendar">
              <div class="weekdays">
                <div v-for="day in ['日', '一', '二', '三', '四', '五', '六']" :key="day" class="weekday">
                  {{ day }}
                </div>
              </div>
              <div class="days">
                <div 
                  v-for="(day, index) in getMonthDays(month)" 
                  :key="index"
                  :class="['day-cell', { 'empty': !day, 'colored': day && hasColor(currentYear, month, day) }]"
                  :style="day ? getDayStyle(currentYear, month, day) : {}"
                >
                  {{ day || '' }}
                </div>
              </div>
            </div>
          </div>
        </div>

        <!-- 单月日历视图 -->
        <div v-else class="month-view">
          <div class="large-calendar">
            <!-- 月份水印 -->
            <div class="month-watermark">
              {{ currentYear }}年 {{ currentMonth }}月
            </div>
            <div class="weekdays-large">
              <div v-for="day in ['日', '一', '二', '三', '四', '五', '六']" :key="day" class="weekday-large">
                {{ day }}
              </div>
            </div>
            <div class="days-large">
              <el-tooltip
                v-for="(day, index) in getMonthDays(currentMonth)" 
                :key="index"
                :content="day ? getDayEventNames(currentYear, currentMonth, day) : ''"
                placement="top"
                effect="dark"
                :disabled="!day || !hasColor(currentYear, currentMonth, day)"
              >
                <div 
                  :class="['day-cell-large', { 'empty': !day, 'clickable': day, 'colored': day && hasColor(currentYear, currentMonth, day) }]"
                  :style="day ? getDayStyle(currentYear, currentMonth, day) : {}"
                  @click="day && toggleDayEvent(currentYear, currentMonth, day)"
                >
                  <span class="day-number">{{ day || '' }}</span>
                </div>
              </el-tooltip>
            </div>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
import { ref, onMounted, computed } from 'vue'
import { Plus, Edit, Back, ArrowUp, ArrowDown, Download, Upload, Delete, Search } from '@element-plus/icons-vue'
import { ElMessage } from 'element-plus'
import dayjs from 'dayjs'
import store2 from 'store2'

export default {
  name: 'App',
  components: {
    Plus,
    Edit,
    Back,
    ArrowUp,
    ArrowDown,
    Download,
    Upload,
    Delete,
    Search
  },
  setup() {
    const currentYear = ref(new Date().getFullYear())
    const currentMonth = ref(1)
    const viewMode = ref('year') // 'year' or 'month'
    const selectedEventId = ref(null)
    
    const isEditMode = ref(false)
    const isClearMode = ref(false)
    const showAddDialog = ref(false)
    const showEditDialog = ref(false)
    const showDayDetailDialog = ref(false)
    const showEventsManageDialog = ref(false)
    const searchKeyword = ref('')
    const selectedDayInfo = ref({
      year: 0,
      month: 0,
      day: 0,
      events: []
    })
    
    const newEventForm = ref({
      name: '',
      color: '#409EFF',
      note: ''
    })
    
    const editEventForm = ref({
      id: '',
      name: '',
      color: '',
      note: ''
    })
    
    const fileInput = ref(null)
    
    const events = ref([])
    const dayEvents = ref({}) // { '2024-1-15': [eventId1, eventId2] }
    
    const predefineColors = [
      '#ff4500', '#ff8c00', '#ffd700', '#90ee90',
      '#00ced1', '#1e90ff', '#c71585', '#ff69b4',
      '#ba55d3', '#9370db', '#3cb371', '#b8860b',
      '#cd5c5c', '#4682b4', '#d2691e', '#dc143c',
      '#00fa9a', '#4169e1', '#ff1493', '#00bfff'
    ]

    // 加载数据
    const loadData = () => {
      const savedEvents = store2.get('calendar_events')
      const savedDayEvents = store2.get('calendar_day_events')
      
      if (savedEvents) {
        events.value = savedEvents
      }
      if (savedDayEvents) {
        dayEvents.value = savedDayEvents
      }
    }

    // 保存数据
    const saveData = () => {
      store2.set('calendar_events', events.value)
      store2.set('calendar_day_events', dayEvents.value)
    }

    // 过滤事件列表（用于搜索）
    const filteredEvents = computed(() => {
      if (!searchKeyword.value.trim()) {
        return events.value
      }
      const keyword = searchKeyword.value.toLowerCase()
      return events.value.filter(event => 
        event.name.toLowerCase().includes(keyword) ||
        (event.note && event.note.toLowerCase().includes(keyword))
      )
    })

    // 切换编辑模式
    const toggleEditMode = () => {
      isClearMode.value = false
      isEditMode.value = !isEditMode.value
      if (isEditMode.value) {
        isClearMode.value = false
      }
      if (!isEditMode.value) {
        selectedEventId.value = null
      }
    }

    // 处理管理对话框中的事件点击
    const handleManageEventClick = (eventId) => {
      isClearMode.value = false
      if (isEditMode.value) {
        // 编辑模式：打开编辑对话框
        const event = events.value.find(e => e.id === eventId)
        if (event) {
          editEventForm.value = {
            id: event.id,
            name: event.name,
            color: event.color,
            note: event.note || ''
          }
          showEditDialog.value = true
        }
      } else {
        // 正常模式：选择事件
        selectEvent(eventId)
        showEventsManageDialog.value = false
      }
    }

    // 切换清除模式
    const toggleClearMode = () => {
      isClearMode.value = !isClearMode.value
      if (isClearMode.value) {
        isEditMode.value = false
        selectedEventId.value = null
      }
    }

    // 处理事件点击
    const handleEventClick = (eventId) => {
      isClearMode.value = false
      if (isEditMode.value) {
        // 编辑模式：打开编辑对话框
        const event = events.value.find(e => e.id === eventId)
        if (event) {
          editEventForm.value = {
            id: event.id,
            name: event.name,
            color: event.color,
            note: event.note || ''
          }
          showEditDialog.value = true
        }
      } else {
        // 正常模式：选择事件用于上色
        selectEvent(eventId)
      }
    }

    // 添加事件
    const addEvent = () => {
      isClearMode.value = false
      if (!newEventForm.value.name.trim()) {
        return
      }
      
      const newEvent = {
        id: Date.now().toString(),
        name: newEventForm.value.name.trim(),
        color: newEventForm.value.color,
        note: newEventForm.value.note.trim()
      }
      
      events.value.push(newEvent)
      newEventForm.value = {
        name: '',
        color: '#409EFF',
        note: ''
      }
      showAddDialog.value = false
      saveData()
    }

    // 保存编辑
    const saveEditEvent = () => {
      const event = events.value.find(e => e.id === editEventForm.value.id)
      if (event) {
        event.name = editEventForm.value.name
        event.color = editEventForm.value.color
        event.note = editEventForm.value.note.trim()
        saveData()
      }
      showEditDialog.value = false
      isEditMode.value = !isEditMode.value
      isClearMode.value = false
    }

    // 确认删除事件
    const confirmDeleteEvent = () => {
      deleteEvent(editEventForm.value.id)
      showEditDialog.value = false
      isEditMode.value = !isEditMode.value
      isClearMode.value = false
    }

    // 删除事件
    const deleteEvent = (eventId) => {
      events.value = events.value.filter(e => e.id !== eventId)
      
      // 删除所有日期中的该事件
      Object.keys(dayEvents.value).forEach(dateKey => {
        dayEvents.value[dateKey] = dayEvents.value[dateKey].filter(id => id !== eventId)
        if (dayEvents.value[dateKey].length === 0) {
          delete dayEvents.value[dateKey]
        }
      })
      
      if (selectedEventId.value === eventId) {
        selectedEventId.value = null
      }
      
      saveData()
    }

    // 选择事件
    const selectEvent = (eventId) => {
      selectedEventId.value = selectedEventId.value === eventId ? null : eventId
    }

    // 切换年份
    const changeYear = (delta) => {
      currentYear.value += delta
    }

    // 进入月份视图
    const enterMonth = (month) => {
      currentMonth.value = month
      viewMode.value = 'month'
    }

    // 退出月份视图
    const exitMonth = () => {
      viewMode.value = 'year'
    }

    // 获取某月的日期数组
    const getMonthDays = (month) => {
      const firstDay = dayjs(`${currentYear.value}-${month}-1`)
      const daysInMonth = firstDay.daysInMonth()
      const startWeekday = firstDay.day()
      
      const days = []
      
      // 填充空白
      for (let i = 0; i < startWeekday; i++) {
        days.push(null)
      }
      
      // 填充日期
      for (let i = 1; i <= daysInMonth; i++) {
        days.push(i)
      }
      
      return days
    }

    // 检查日期是否有颜色
    const hasColor = (year, month, day) => {
      const dateKey = `${year}-${month}-${day}`
      const eventIds = dayEvents.value[dateKey] || []
      return eventIds.length > 0
    }

    // 获取日期的事件名称列表
    const getDayEventNames = (year, month, day) => {
      const dateKey = `${year}-${month}-${day}`
      const eventIds = dayEvents.value[dateKey] || []
      
      if (eventIds.length === 0) {
        return ''
      }
      
      const eventNames = eventIds
        .map(id => events.value.find(e => e.id === id)?.name.split(' ')[1])
        .filter(Boolean)
      
      return eventNames.join('、')
    }

    // 获取某月的事件种类数（去重）
    const getMonthEventTypes = (year, month) => {
      const firstDay = dayjs(`${year}-${month}-1`)
      const daysInMonth = firstDay.daysInMonth()
      const uniqueEventIds = new Set()
      
      for (let day = 1; day <= daysInMonth; day++) {
        const dateKey = `${year}-${month}-${day}`
        const eventIds = dayEvents.value[dateKey] || []
        eventIds.forEach(id => uniqueEventIds.add(id))
      }
      
      return uniqueEventIds.size
    }

    // 获取某月的事件总数（不去重）
    const getMonthEventCount = (year, month) => {
      const firstDay = dayjs(`${year}-${month}-1`)
      const daysInMonth = firstDay.daysInMonth()
      let totalCount = 0
      
      for (let day = 1; day <= daysInMonth; day++) {
        const dateKey = `${year}-${month}-${day}`
        const eventIds = dayEvents.value[dateKey] || []
        totalCount += eventIds.length
      }
      
      return totalCount
    }

    // 获取全年的事件种类数（去重）
    const getTotalEventTypes = () => {
      const uniqueEventIds = new Set()
      
      Object.values(dayEvents.value).forEach(eventIds => {
        eventIds.forEach(id => uniqueEventIds.add(id))
      })
      
      return uniqueEventIds.size
    }

    // 获取全年的事件总数（不去重）
    const getTotalEventCount = () => {
      let totalCount = 56
      
      Object.values(dayEvents.value).forEach(eventIds => {
        totalCount += eventIds.length
      })
      
      return totalCount
    }

    // 获取日期的样式
    const getDayStyle = (year, month, day) => {
      const dateKey = `${year}-${month}-${day}`
      const eventIds = dayEvents.value[dateKey] || []
      
      if (eventIds.length === 0) {
        return {}
      }
      
      const colors = eventIds
        .map(id => events.value.find(e => e.id === id)?.color)
        .filter(Boolean)
      
      if (colors.length === 0) {
        return {}
      }
      
      if (colors.length === 1) {
        return {
          backgroundColor: colors[0]
        }
      }
      
      // 多个颜色，使用渐变，在边界处添加4%的渐变过渡
      const colorStops = colors.map((color, index, arr) => {
        const segmentSize = 100 / arr.length
        const start = index * segmentSize
        const end = (index + 1) * segmentSize
        
        // 渐变范围：前后4%
        const gradientRange = 4
        
        if (index === 0) {
          // 第一个颜色：只在结束处渐变
          return `${color} 0%, ${color} ${end - gradientRange}%`
        } else if (index === arr.length - 1) {
          // 最后一个颜色：只在开始处渐变
          return `${color} ${start + gradientRange}%, ${color} 100%`
        } else {
          // 中间颜色：两端都渐变
          return `${color} ${start + gradientRange}%, ${color} ${end - gradientRange}%`
        }
      }).join(', ')
      
      return {
        background: `linear-gradient(135deg, ${colorStops})`
      }
    }

    // 切换日期事件
    const toggleDayEvent = (year, month, day) => {
      // 清除模式：清除日期的所有颜色
      if (isClearMode.value) {
        const dateKey = `${year}-${month}-${day}`
        if (dayEvents.value[dateKey]) {
          delete dayEvents.value[dateKey]
          saveData()
          ElMessage.success('已清除该日期的颜色')
        }
        return
      }

      // 有选择事件：添加/移除事件
      if (selectedEventId.value) {
        const dateKey = `${year}-${month}-${day}`
        
        if (!dayEvents.value[dateKey]) {
          dayEvents.value[dateKey] = []
        }
        
        const eventIndex = dayEvents.value[dateKey].indexOf(selectedEventId.value)
        
        if (eventIndex > -1) {
          // 已存在，移除
          dayEvents.value[dateKey].splice(eventIndex, 1)
          if (dayEvents.value[dateKey].length === 0) {
            delete dayEvents.value[dateKey]
          }
        } else {
          // 不存在，添加
          dayEvents.value[dateKey].push(selectedEventId.value)
        }
        
        saveData()
        return
      }

      // 无选择事件且非编辑/清除模式：显示日期详情
      if (!isEditMode.value && !isClearMode.value) {
        showDayDetail(year, month, day)
      }
    }

    // 显示日期详情
    const showDayDetail = (year, month, day) => {
      const dateKey = `${year}-${month}-${day}`
      const eventIds = dayEvents.value[dateKey] || []
      
      const eventDetails = eventIds
        .map(id => events.value.find(e => e.id === id))
        .filter(Boolean)
      
      selectedDayInfo.value = {
        year,
        month,
        day,
        events: eventDetails
      }
      
      showDayDetailDialog.value = true
    }

    // 导出数据
    const exportData = () => {
      const data = {
        events: events.value,
        dayEvents: dayEvents.value,
        exportDate: new Date().toISOString(),
        version: '1.0'
      }
      
      const dataStr = JSON.stringify(data, null, 2)
      const blob = new Blob([dataStr], { type: 'application/json' })
      const url = URL.createObjectURL(blob)
      
      const link = document.createElement('a')
      link.href = url
      link.download = `calendar-data-${dayjs().format('YYYY-MM-DD')}.json`
      document.body.appendChild(link)
      link.click()
      document.body.removeChild(link)
      URL.revokeObjectURL(url)
      
      ElMessage.success('数据导出成功')
    }

    // 触发文件选择
    const triggerImport = () => {
      fileInput.value?.click()
    }

    // 导入数据
    const importData = (event) => {
      const file = event.target.files?.[0]
      if (!file) return
      
      const reader = new FileReader()
      reader.onload = (e) => {
        try {
          const data = JSON.parse(e.target.result)
          
          if (!data.events || !data.dayEvents) {
            ElMessage.error('数据格式错误')
            return
          }
          
          events.value = data.events
          dayEvents.value = data.dayEvents
          saveData()
          
          ElMessage.success('数据导入成功')
        } catch (error) {
          ElMessage.error('导入失败：文件格式错误')
          console.error(error)
        }
      }
      
      reader.readAsText(file)
      event.target.value = '' // 清空input，允许重复导入同一文件
    }

    onMounted(() => {
      loadData()
    })

    return {
      currentYear,
      currentMonth,
      viewMode,
      selectedEventId,
      isEditMode,
      isClearMode,
      showAddDialog,
      showEditDialog,
      showDayDetailDialog,
      showEventsManageDialog,
      searchKeyword,
      filteredEvents,
      selectedDayInfo,
      newEventForm,
      editEventForm,
      fileInput,
      events,
      dayEvents,
      predefineColors,
      toggleEditMode,
      toggleClearMode,
      handleEventClick,
      handleManageEventClick,
      addEvent,
      saveEditEvent,
      confirmDeleteEvent,
      deleteEvent,
      selectEvent,
      changeYear,
      enterMonth,
      exitMonth,
      getMonthDays,
      hasColor,
      getDayEventNames,
      getMonthEventTypes,
      getMonthEventCount,
      getTotalEventTypes,
      getTotalEventCount,
      getDayStyle,
      toggleDayEvent,
      showDayDetail,
      exportData,
      triggerImport,
      importData
    }
  }
}
</script>

